    window.airgap = window.airgap || {};

    window.airgap.ready((airgap) => {
        airgap.addEventListener('consent-change', ({ detail: { consent, oldConsent, changes } }) => {
            if (
                oldConsent.purposes['Functional'] == false &&
                consent.purposes['Functional'] == true
            ) {
                airgap.setConsent(window.airgapScriptLoadEvent, {
                    Functional: false,
                });
            }
        });
    }); 

    document.addEventListener("DOMContentLoaded", function () {
        
        if ('airgap' in window && 'transcend' in window) {
            const cpraButton = document.getElementById('cpra_button');
            cpraButton.onclick = (e) => {
                e.preventDefault();
                transcend.showConsentManager({ viewState: 'AcceptAllRejectAllToggle' });
            };

            window.airgap.ready(async (airgap) => {
                //await airgap.sync();
                let userConsent = airgap.getConsent();
                console.info('airgap --> userConsent', userConsent);                
            });
        }
    });

form.script:
                require(['jquery', 'jquery-ui', 'headroom', 'jquery-headroom'], function($) {
                    var headroomResize = function() {
                        if( window.matchMedia('(min-width: 1201px)').matches) {
                            $('html').headroom('destroy').removeData('headroom').headroom({ offset: 50});
                        } else {
                            $('html').headroom('destroy').removeData('headroom').headroom({ offset: 0});
                        }
                    }

                    headroomResize();

                    $(window).resize(function() {
                        headroomResize();
                    });

                    $(".main-header").on('mouseenter', '.c-navigation--main.c-navigation--desktop .c-navigation__parent .c-navigation__url--level-1', function() {
                        $('.main-header__nav').addClass('hovered');
                    });
                    $(".main-header").on('mouseleave', '.c-navigation--main.c-navigation--desktop .c-navigation__parent .c-navigation__url--level-1', function() {
                        $('.main-header__nav').removeClass('hovered');
                    });

                    $(".main-header").on('mouseenter', '.c-navigation--main.c-navigation--desktop .c-navigation__level-2', function() {
                        $('.main-header__nav').addClass('hovered');
                    });
                    $(".main-header").on('mouseleave', '.c-navigation--main.c-navigation--desktop .c-navigation__level-2', function() {
                        $('.main-header__nav').removeClass('hovered');
                    });

                });
